import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { cueById, type Mode } from "../shared/catalog.ts";
import { newGame, play } from "../shared/game/engine.ts";
import { dailyPhysics, dailyRack } from "../shared/game/daily.ts";
import type { StrikeCmd } from "../shared/game/types.ts";

// Golden event/ball hashes were generated by commit 1b27dda, before the physics update. They cover a break,
// a jumping stroke, spin, finesse and multiple venues/modes, so saved match logs stay reproducible.
const cases: [Mode, string, number, StrikeCmd, string][] = [
  [8, "hall", 1234567, { k: "strike", dx: 1000000, dy: 0, power: 850, tx: 0, ty: 0, el: 0 }, "469550c27a5c553f6ca21dcfa4c40fcd7dec093cd55f29bf309969516a67ad53"],
  [9, "garage", 743, { k: "strike", dx: 998000, dy: 63214, power: 1000, tx: -250, ty: 150, el: 40, tipChalk: 0.5 }, "315ec19bbaadf1a6debe7d9f5aa348e3e5a4a5ac6ddb6893a69b6c506a22f33d"],
  [10, "arena", 829, { k: "strike", dx: 999600, dy: -28270, power: 300, tx: 370, ty: -400, el: 0, handChalk: 0.7 }, "8d815ed28816a9bf8c2c6bc38f889777f528f6bfa9c6d78423ec6f71f67868ed"],
  [15, "sanctum", 17, { k: "strike", dx: 1000000, dy: 0, power: 700, tx: 150, ty: 190, el: 18, finesse: 500 }, "1cbb33fec1548ad1a8bfd1c4d642d8903c49d60ee818dd03f30c1018307a01bf"],
];

test("pre-update matches reproduce their original ball positions and event streams", () => {
  for (const [mode, table, seed, cmd, expected] of cases) {
    const st = newGame(mode, table, seed, 0, 1);
    assert.equal(st.physics, undefined);
    const { sim } = play(st, cmd, cueById("maple"));
    const actual = createHash("sha256").update(JSON.stringify({ events: sim.events, balls: sim.balls })).digest("hex");
    assert.equal(actual, expected, `${mode}-ball at ${table}`);
  }
  assert.equal(newGame(8, "garage", 1, 0).physics, 2);
});

test("daily physics changes only at the agreed UTC-day boundary, including late runs", () => {
  assert.equal(dailyPhysics(99, 100), 1);
  assert.equal(dailyPhysics(100, 100), 2);
  assert.equal(dailyRack(99, dailyPhysics(99, 100)).physics, undefined);
  assert.equal(dailyRack(100, dailyPhysics(100, 100)).physics, 2);
});
